import React, { useState, useEffect } from 'react';
import axios from 'axios';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from 'recharts';

const Jubilacion = () => {
  const [predictions, setPredictions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        // Solicitar predicciones desde tu API
        const predResponse = await axios.get('http://localhost:5000/api/predicciones');
        console.log('Predicciones:', predResponse.data); // Log para depuración
        setPredictions(predResponse.data);
        setLoading(false);
      } catch (error) {
        console.error(error); // Log del error
        setError('Error al cargar los datos.');
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) return <p>Cargando...</p>;
  if (error) return <p>{error}</p>;

  return (
    <div>
      <h2>Predicción de Tipo de Cambio USD/EUR para Jubilación</h2>
      <ResponsiveContainer width="100%" height={400}>
        <LineChart data={predictions}>
          <CartesianGrid strokeDasharray="3 3" />
          <XAxis dataKey="fecha" />
          <YAxis />
          <Tooltip />
          <Legend />
          <Line type="monotone" dataKey="valor" stroke="#8884d8" activeDot={{ r: 8 }} />
        </LineChart>
      </ResponsiveContainer>
    </div>
  );
};

export default Jubilacion;
